grab_ability_results = []

for mass in new_test_masses:
    for velocity in new_test_velocities:
        for potential in new_test_potentials:
            for change_potential in total_change_potentials:
                for stable_mass in total_stable_masses:
                    for surface_area in surface_areas:
                        # Compute energy using the refined formula with grab-ability and E=mc^2
                        energy_relativistic = particle_physics_energy(mass, velocity)
                        energy_grab = refined_with_grab_ability(
                            mass, velocity, potential, change_potential, stable_mass, surface_area
                        )

                        # Calculate percentage deviation
                        deviation = abs(energy_grab - energy_relativistic) / energy_relativistic * 100

                        # Record the results
                        grab_ability_results.append(
                            (mass, velocity, potential, change_potential, stable_mass, surface_area, deviation)
                        )

# Convert results to a structured DataFrame
grab_ability_df = pd.DataFrame(grab_ability_results, columns=[
    "Mass (kg)", "Velocity (c)", "Potential", "Total Change Potential",
    "Total Stable Mass", "Surface Area", "Deviation (%)"
])

# Display results for analysis
import ace_tools as tools; tools.display_dataframe_to_user(name="Refined Grab-Ability Formula Results", dataframe=grab_ability_df)

# Highlight extreme deviations for review
extreme_grab_ability_deviations = grab_ability_df[grab_ability_df["Deviation (%)"] > 100]
tools.display_dataframe_to_user(name="Extreme Deviation Cases with Grab-Ability", dataframe=extreme_grab_ability_deviations)

# Re-attempt recalculation and comparison between earlier and current models
# Using restructured inputs for comparison

# Calculate earlier results
earlier_results = []

for mass in earlier_test_masses:
    for velocity in earlier_test_velocities:
        for potential in earlier_test_potentials:
            for change_potential in earlier_change_potentials:
                for stable_mass in earlier_stable_masses:
                    for surface_area in earlier_surface_areas:
                        # Compute energy using the earlier model
                        energy_relativistic = mass * (3e8)**2
                        energy_earlier = earlier_model(
                            mass, velocity, potential, change_potential, stable_mass, surface_area
                        )
                        deviation = abs(energy_earlier - energy_relativistic) / energy_relativistic * 100
                        earlier_results.append(
                            (mass, velocity, potential, change_potential, stable_mass, surface_area, deviation)
                        )

earlier_df = pd.DataFrame(earlier_results, columns=[
    "Mass (kg)", "Velocity (c)", "Potential", "Total Change Potential",
    "Total Stable Mass", "Surface Area", "Deviation (%)"
])

average_deviation_earlier = earlier_df["Deviation (%)"].mean()

# Recalculate for the current model
current_results = []

for mass in earlier_test_masses:
    for velocity in earlier_test_velocities:
        for potential in earlier_test_potentials:
            for change_potential in earlier_change_potentials:
                for stable_mass in earlier_stable_masses:
                    for surface_area in earlier_surface_areas:
                        # Compute energy using the current model
                        energy_relativistic = mass * (3e8)**2
                        energy_current = refined_with_dampened_surface_area(
                            mass, velocity, potential, change_potential, stable_mass, surface_area
                        )
                        deviation = abs(energy_current - energy_relativistic) / energy_relativistic * 100
                        current_results.append(
                            (mass, velocity, potential, change_potential, stable_mass, surface_area, deviation)
                        )

current_df = pd.DataFrame(current_results, columns=[
    "Mass (kg)", "Velocity (c)", "Potential", "Total Change Potential",
    "Total Stable Mass", "Surface Area", "Deviation (%)"
])

average_deviation_current = current_df["Deviation (%)"].mean()

# Compare results
average_improvement = average_deviation_earlier - average_deviation_current
percentage_improvement = (average_improvement / average_deviation_earlier) * 100

comparison_summary = {
    "Average Deviation (Earlier Model)": average_deviation_earlier,
    "Average Deviation (Current Model)": average_deviation_current,
    "Improvement (Absolute)": average_improvement,
    "Improvement (Percentage)": percentage_improvement,
}

